import { z } from "zod";
const zColor = z.string();
// these come from pico.css + our own var additions
const zThemeVars = z
    .object({
    font_family: z.string(),
    primary: zColor,
    primary_hover: zColor,
    primary_focus: zColor,
})
    .partial();
const zThemeProps = z
    .object({
    title: z.string(),
    favicon: z.string().url(),
    fonts: z.array(z.string()),
    mode: z.enum(["dark", "light"]),
    direction: z.enum(["ltr", "rtl"]),
    hide_login_menu: z.boolean(),
    light: zThemeVars,
    dark: zThemeVars,
})
    .partial();
export function Theme(define) {
    return define("Theme")
        .props(zThemeProps)
        .render((props) => ({
        title: props.title,
        favicon: props.favicon,
        fonts: props.fonts,
        mode: props.mode,
        direction: props.direction,
        hide_login_menu: props.hide_login_menu,
        light: props.light,
        dark: props.dark,
    }));
}
